def compute(vars):
    owned_miles = vars["v1"]
    total_miles = vars["v2"]

    if total_miles == 0:
        return None

    owned_percent = (owned_miles / total_miles) * 100

    return {
        "value": owned_percent,
        "trace": {
            "owned_network_route_miles": owned_miles,
            "total_network_route_miles": total_miles,
            "owned_percent": owned_percent,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
